// js
// Tax or a contribution came out overpaid. The HR controller pays it back with an entry on the Statutory refund item, in Events.
if (ctx.reads.obligation.length > 0) return [];
const year = String(get(first(ctx.reads.payroll_run), 'pay_date', '')).slice(0, 4);
const over = get(ctx.entry, 'breakdown.statutory', []).filter((row) => Number(get(row, 'overpaid', 0)) > 0);
const overpaid = sum(over.map((row) => Number(get(row, 'overpaid', 0))));
const what = over.every((row) => row.kind === 'TAX') ? 'Tax' : over.map((row) => row.code).join(', ');
return [{
	entity_id: ctx.entry.entity_id,
	employee_id: ctx.entry.employee_id,
	employment_id: ctx.entry.employment_id,
	title: what + ' overpaid in ' + year + ': enter ' + overpaid + ' on Statutory refund' + (what === 'Tax' ? '' : '; any employer share comes back from the agency'),
	occurrence_key: occurrence_key(['PH', 'TAX_REFUND', ctx.entry.id])
}];
